-- Run after fixture, old migration/tests, setup and corrective migration. LOCAL only.
SELECT test_assert((SELECT approved FROM profiles WHERE id='00000000-0000-0000-0000-000000000005'),'admin remains approved');
SELECT test_assert((SELECT bool_and(approved) FROM profiles WHERE id IN ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003')),'three matching dummy seeds approved');
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='00000000-0000-0000-0000-000000000004'),'ordinary user role and seed ID alone do not approve');
SELECT test_assert((SELECT NOT approved AND rejection_reason IS NULL FROM profiles WHERE id='10000000-0000-0000-0000-000000000001'),'manual approval reset to pending, not rejected');
SELECT test_assert((SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000002'),'test flag approved');
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000003'),'test viewing preference is not test identity');
SELECT test_assert((SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000004'),'normalized confirmed auth Kat approved');
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000005'),'spoofed profile email does not approve');
SELECT test_assert((SELECT bool_and(approved) FROM profiles WHERE id IN ('10000000-0000-0000-0000-000000000006','10000000-0000-0000-0000-000000000007')),'both auth seed sources approved');
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000008'),'unconfirmed Kat does not approve');
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',false);
INSERT INTO user_roles VALUES('10000000-0000-0000-0000-000000000001','user');
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000001'),'user role grant does not approve');
UPDATE profiles SET approved=true WHERE id='10000000-0000-0000-0000-000000000001';
DELETE FROM user_roles WHERE user_id='10000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000001'),'user role deletion preserves explicit review');
UPDATE profiles SET approved=false WHERE id='10000000-0000-0000-0000-000000000001';
INSERT INTO user_roles VALUES('10000000-0000-0000-0000-000000000001','admin');
SELECT test_assert((SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000001'),'admin role grant approves');
UPDATE user_roles SET role='user' WHERE user_id='10000000-0000-0000-0000-000000000001';
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000001'),'admin demotion resets regular user despite user role');
INSERT INTO user_roles VALUES('10000000-0000-0000-0000-000000000004','admin');
DELETE FROM user_roles WHERE user_id='10000000-0000-0000-0000-000000000004';
SELECT test_assert((SELECT approved FROM profiles WHERE id='10000000-0000-0000-0000-000000000004'),'Kat retains exception on admin removal');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
SELECT test_assert((SELECT count(*) FROM profiles)=1,'reset ordinary account sees self only');
SELECT test_assert((SELECT count(*) FROM investor_profiles)=0,'reset ordinary account cannot browse');
SELECT test_denied($s$UPDATE profiles SET approved=true WHERE id=auth.uid()$s$);
SELECT test_denied($s$UPDATE profiles SET is_test_account=true WHERE id=auth.uid()$s$);
SELECT test_denied($s$SELECT approval_exception(auth.uid())$s$);
UPDATE profiles SET is_test_mode=true WHERE id=auth.uid();
SELECT test_assert(NOT (SELECT approved FROM profiles WHERE id=auth.uid()),'mode preference still cannot approve');
RESET ROLE;
